insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008013','Controle de estoque · prática','Relacione cada conceito à sua definição.','["Fornece insumos","Armazena produtos","Entrega ao destino"]'::jsonb,'O saldo é 20 − 7 = 13. O controle registra movimentações; a distribuição conecta o estoque ao destino, sem eliminar todos os riscos.','Etapa de trilha',40,'00000000-0000-4000-8000-000000000011','matching','{"labels":["Fornecedor","Estoque","Distribuição"]}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008014','Preparação de pedidos · prática','Planeje o envio de um pedido com três produtos. Descreva conferência, embalagem e registro da saída.','[]'::jsonb,'O saldo é 20 − 7 = 13. O controle registra movimentações; a distribuição conecta o estoque ao destino, sem eliminar todos os riscos.','Etapa de trilha',10,'00000000-0000-4000-8000-000000000011','challenge','{"criteria":["Listei os produtos e quantidades","Descrevi a conferência antes do envio","Registrei a saída no estoque"],"minLength":120}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008015','Leitura ativa · prática','Qual palavra é proparoxítona?','["café","árvore","papel"]'::jsonb,'Proparoxítonas têm a antepenúltima sílaba tônica. Substantivos nomeiam; verbos expressam ação ou estado; adjetivos caracterizam.','Etapa de trilha',40,'00000000-0000-4000-8000-000000000010','choice','{}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008016','Ortografia e revisão · prática','Relacione cada conceito à sua definição.','["Nomeia","Expressa ação ou estado","Caracteriza"]'::jsonb,'Proparoxítonas têm a antepenúltima sílaba tônica. Substantivos nomeiam; verbos expressam ação ou estado; adjetivos caracterizam.','Etapa de trilha',40,'00000000-0000-4000-8000-000000000010','matching','{"labels":["Substantivo","Verbo","Adjetivo"]}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008017','Comunicação de projetos · prática','Escreva um parágrafo apresentando um projeto da escola. Identifique a ideia principal e revise a ortografia.','[]'::jsonb,'Proparoxítonas têm a antepenúltima sílaba tônica. Substantivos nomeiam; verbos expressam ação ou estado; adjetivos caracterizam.','Etapa de trilha',10,'00000000-0000-4000-8000-000000000010','challenge','{"criteria":["Apresentei uma ideia principal","Usei um exemplo para sustentá-la","Revisei pontuação e acentuação"],"minLength":120}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008018','Células e organelas · prática','Qual grupo de plantas produz flores e frutos?','["Briófitas","Angiospermas","Pteridófitas"]'::jsonb,'Angiospermas produzem flores e frutos; briófitas não possuem vasos verdadeiros. Cloroplastos participam da fotossíntese.','Etapa de trilha',40,'00000000-0000-4000-8000-000000000012','choice','{}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008019','Grupos de plantas · prática','Relacione cada conceito à sua definição.','["Absorção de água e sais","Principal órgão fotossintetizante","Reprodução das angiospermas"]'::jsonb,'Angiospermas produzem flores e frutos; briófitas não possuem vasos verdadeiros. Cloroplastos participam da fotossíntese.','Etapa de trilha',40,'00000000-0000-4000-8000-000000000012','matching','{"labels":["Raiz","Folha","Flor"]}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008020','Observação científica · prática','Observe uma planta sem arrancá-la. Descreva raiz quando visível, caule e folhas; explique uma função de cada órgão observado.','[]'::jsonb,'Angiospermas produzem flores e frutos; briófitas não possuem vasos verdadeiros. Cloroplastos participam da fotossíntese.','Etapa de trilha',10,'00000000-0000-4000-8000-000000000012','challenge','{"criteria":["Registrei o que realmente observei","Descrevi pelo menos dois órgãos","Relacionei os órgãos às suas funções"],"minLength":120}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008021','Grandezas e unidades · prática','Qual é a unidade de força no Sistema Internacional?','["Joule","Newton","Watt"]'::jsonb,'Força é medida em newtons; energia em joules; potência em watts. Massa é medida em quilogramas, enquanto peso é uma força.','Etapa de trilha',40,'00000000-0000-4000-8000-000000000013','choice','{}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008022','Movimento · prática','Relacione cada conceito à sua definição.','["Newton","Joule","Watt"]'::jsonb,'Força é medida em newtons; energia em joules; potência em watts. Massa é medida em quilogramas, enquanto peso é uma força.','Etapa de trilha',40,'00000000-0000-4000-8000-000000000013','matching','{"labels":["Força","Energia","Potência"]}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008023','Medição e análise · prática','Descreva como medir a velocidade média em um trajeto seguro. Apresente valores hipotéticos, unidades e cálculo.','[]'::jsonb,'Força é medida em newtons; energia em joules; potência em watts. Massa é medida em quilogramas, enquanto peso é uma força.','Etapa de trilha',10,'00000000-0000-4000-8000-000000000013','challenge','{"criteria":["Defini deslocamento e tempo","Informei as unidades","Calculei deslocamento dividido pelo tempo"],"minLength":120}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008024','Reconhecer habilidades · prática','Qual evidência comunica melhor uma habilidade?','["Uma lista de elogios genéricos","Um projeto com contribuição e resultado descritos","Uma competência inventada"]'::jsonb,'Uma contribuição concreta pode ser explicada e verificada.','Etapa de trilha',40,'00000000-0000-4000-8000-000000000015','choice','{}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008025','Documentar projetos · prática','Relacione as partes do relato de um projeto.','["Situação e problema","O que você fez","O que observou e aprendeu"]'::jsonb,'Compare a finalidade de cada conceito com o conteúdo desta etapa.','Etapa de trilha',40,'00000000-0000-4000-8000-000000000015','matching','{"labels":["Contexto","Contribuição","Resultado"]}'::jsonb) on conflict(id) do nothing;
insert into public.questions (id,title,prompt,options,explanation,category,xp,subject_id,kind,payload) values ('00000000-0000-4000-8000-000000008026','Preparar uma candidatura · prática','Escreva uma apresentação para uma vaga fictícia. Use uma experiência real sua e indique algo que ainda está aprendendo.','[]'::jsonb,'Relato autodeclarado para revisão e aprendizagem.','Etapa de trilha',10,'00000000-0000-4000-8000-000000000015','challenge','{"criteria":["Expliquei meu interesse","Citei uma contribuição verificável","Evitei inventar experiência"],"minLength":120}'::jsonb) on conflict(id) do nothing;
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000300','00000000-0000-4000-8000-000000000200','Fundamentos','Um algoritmo é uma sequência finita de passos para resolver um problema. Antes de escrever código, descreva a entrada, o processamento e a saída.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000301','00000000-0000-4000-8000-000000000200','Variáveis','Variáveis associam um nome a um valor. Em Dart, int armazena inteiros; double armazena decimais; String representa texto; bool representa verdadeiro ou falso.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000302','00000000-0000-4000-8000-000000000200','Lógica','Uma condição produz verdadeiro ou falso. Combine comparações com && (e), || (ou) e ! (negação).
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000303','00000000-0000-4000-8000-000000000200','Maratona 1','Planeje um programa de cadastro de três produtos. Para cada um, registre nome, preço e quantidade. Calcule o total do estoque.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000304','00000000-0000-4000-8000-000000000200','Condicionais','if executa um bloco quando sua condição é verdadeira. else permite tratar o caso contrário.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000305','00000000-0000-4000-8000-000000000200','Loops','Use um laço quando uma operação precisa se repetir. Um for tem inicialização, condição e atualização.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000306','00000000-0000-4000-8000-000000000200','Arrays','Em Dart, List organiza valores em sequência. O primeiro índice é 0.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000320','00000000-0000-4000-8000-000000000201','Requisições HTTP','O cliente envia uma requisição a um servidor. Método, caminho, cabeçalhos e corpo descrevem a operação. A resposta inclui status e conteúdo.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000321','00000000-0000-4000-8000-000000000201','APIs REST','Recursos podem ser representados por endereços como /produtos. Defina contratos de entrada e saída, valide dados no servidor e diferencie erros de validação de falhas internas.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp) values ('00000000-0000-4000-8000-000000000322','00000000-0000-4000-8000-000000000201','Microservices Patterns','Separar serviços cria limites claros, mas também falhas de rede e desafios de consistência. Use timeouts, operações idempotentes e contratos versionados.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003000','00000000-0000-4000-8000-000000002000','HTML semântico','HTML descreve a estrutura do documento. Use títulos em ordem e elementos como main, nav e button conforme sua função. Um botão executa uma ação; um link leva a outro endereço. Crie no papel o esqueleto semântico de uma página de estudos.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003001','00000000-0000-4000-8000-000000002000','CSS responsivo','CSS define apresentação. Use grid ou flex para distribuir conteúdo, unidades flexíveis e limites de largura. Comece pela tela pequena; mantenha rótulos legíveis e foco visível. Descreva como sua página se reorganiza ao ganhar espaço.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003002','00000000-0000-4000-8000-000000002000','Publicação acessível','Antes de publicar, verifique títulos, alternativas textuais, contraste e navegação por teclado. Teste links e formulários. Descreva três verificações que faria em uma página de estudos.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003010','00000000-0000-4000-8000-000000002001','Entender o problema','Comece pelo problema e pelo contexto. Uma entrevista investiga experiências, não confirma uma solução pronta. Escreva uma pergunta aberta sobre como estudantes encontram materiais e indique qual dúvida a pesquisa resolve.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003011','00000000-0000-4000-8000-000000002001','Estruturar a interface','Agrupe informações relacionadas, estabeleça uma hierarquia de títulos e mantenha padrões de navegação. Desenhe uma tela de biblioteca com busca, matérias e indicação de leitura. Explique a prioridade visual escolhida.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003012','00000000-0000-4000-8000-000000002001','Testar com pessoas','No teste de usabilidade, proponha uma tarefa realista e observe sem ensinar o caminho. Registre erros, hesitações e comentários. Planeje uma tarefa para encontrar um material e descreva como perceberá que foi concluída.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003020','00000000-0000-4000-8000-000000002002','Rede local','DNS resolve nomes. Um roteador encaminha pacotes. Uma conexão Wi-Fi local não garante acesso à internet.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003021','00000000-0000-4000-8000-000000002002','Endereçamento e DNS','DNS resolve nomes. Um roteador encaminha pacotes. Uma conexão Wi-Fi local não garante acesso à internet.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003022','00000000-0000-4000-8000-000000002002','Diagnóstico de conexão','Crie um roteiro de diagnóstico quando um dispositivo conecta ao Wi-Fi mas não abre sites. Separe rede local, internet e resolução de nomes.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003030','00000000-0000-4000-8000-000000002003','Grandezas elétricas','Resistores limitam corrente. Resistência é medida em ohms, corrente em amperes e tensão em volts. Confira limites dos componentes.
insert into public.modules (id,track_id,title,body,position,prerequisite_id,xp,question_id) values ('00000000-0000-4000-8000-000000003031','00000000-0000-4000-8000-000000002003','Circuito com resistor','Resistores limitam corrente. Resistência é medida em ohms, corrente em amperes e tensão em volts. Confira limites dos componentes.
